 @Test void tc08_inventoryUsesCheckinSnapshotNotCatalogue(){var a=active("0",false,BigDecimal.ZERO,true);long co=request(a);f.db.sql("UPDATE room_assets SET name='Changed catalogue',condition_status='DAMAGED' WHERE room_id=:id").param("id",a.room).update();inspect(a,co);var detail=workflow.detail(f.tenant,a.contract);assertThat(detail.get("initialAssets").toString()).contains("Original fan").doesNotContain("Changed catalogue");}
 @Test void tc09_unconfirmedDamageDoesNotCreateDebt(){var a=active("0",false);long co=request(a);inspect(a,co);charge(co,"150000",false);assertThat(f.inTx(()->workflow.preview(f.owner,co)).newCharges()).isZero();assertThat(count("invoices","contract_id="+a.contract)).isZero();}
 @Test void tc10_sameDamageCannotBeAddedTwice(){var a=active("0",false);long co=request(a);var r=new ChargeRequest("ONE-INCIDENT","DAMAGE","Fan repair",n("150000"),"PHOTO","Verified responsibility",null);f.run(()->workflow.proposeCharge(f.owner,co,r));assertThatThrownBy(()->f.run(()->workflow.proposeCharge(f.owner,co,r))).isInstanceOf(org.springframework.dao.DuplicateKeyException.class);assertThat(count("checkout_verified_charges","checkout_id="+co)).isOne();}
 @Test void tc11_finalMetersArePersisted(){var a=active("0",true);long co=request(a);inspect(a,co,n("1380"),n("262"),false,false,null,assets(a));assertThat((BigDecimal)co(co).get("final_electricity_reading")).isEqualByComparingTo("1380");assertThat(f.inTx(()->workflow.preview(f.owner,co)).newCharges()).isEqualByComparingTo("695000");}
 @Test void tc12_onlyUnbilledConsumptionIsCharged(){var a=active("0",true);record(a,"1500","260");long old=oldDebt(a,"0");pay(old,"1075000");long co=request(a);inspect(a,co,n("1550"),n("262"),false,false,null,assets(a));var p=f.inTx(()->workflow.preview(f.owner,co));assertThat(p.oldDebt()).isZero();assertThat(p.lines().stream().filter(x->x.type().equals("ELECTRICITY")).findFirst().orElseThrow().amount()).isEqualByComparingTo("175000");assertThat(p.newCharges()).isEqualByComparingTo("215000");}
 @Test void tc13_dailyRentIncludesHandoverOnlyWhenAgreed(){var a=active("0",false,n("3000000"),false);f.run(()->billing.proration(f.owner,a.contract,new MonthlyBillingService.Proration("ACTUAL_DAYS","Daily final rent agreed")));long co=request(a);inspect(a,co,null,null,true,false,null,assets(a));assertThat(f.inTx(()->workflow.preview(f.owner,co)).newCharges()).isEqualByComparingTo(n("3000000").divide(BigDecimal.valueOf(period.lengthOfMonth()),2,java.math.RoundingMode.HALF_UP));}
 @Test void tc14_alreadyBilledServiceIsNotRepeated(){var a=active("0",false);f.run(()->billing.service(f.owner,a.contract,new MonthlyBillingService.ServiceRule("PARKING","Parking","QUANTITY","vehicle",n("50000"),n("2"),LocalDate.now(),null,false,"Two vehicles agreed")));oldDebt(a,"0");long co=request(a);inspect(a,co);var p=f.inTx(()->workflow.preview(f.owner,co));assertThat(p.newCharges()).isZero();assertThat(p.oldDebt()).isEqualByComparingTo("100000");}
 @Test void tc15_oldDebtIsNotDuplicatedIntoSettlementInvoice(){var a=active("0",false);oldDebt(a,"500000");long co=request(a);inspect(a,co);charge(co,"200000",true);approve(a,co,true);apply(a,co);assertThat(f.db.sql("SELECT total_amount FROM invoices WHERE code=:code").param("code","QT-"+co).query(BigDecimal.class).single()).isEqualByComparingTo("200000");assertThat(f.accounting.outstandingDebt(3,a.property)).isEqualByComparingTo("700000");}
 @Test void tc16_threeMillionDepositOneMillionObligationRefundsTwoMillion(){var a=active("3000000",true);record(a,"1250","250");oldDebt(a,"500000");long co=request(a);inspect(a,co,n("1300"),n("256.25"),false,false,null,assets(a));charge(co,"200000",true);var p=f.inTx(()->workflow.preview(f.owner,co));assertThat(p.oldDebt()).isEqualByComparingTo("500000");assertThat(p.newCharges()).isEqualByComparingTo("500000");assertThat(p.deduction()).isEqualByComparingTo("1000000");assertThat(p.refund()).isEqualByComparingTo("2000000");approve(a,co,true);apply(a,co);assertThat(f.balance(a.deposit)).isEqualByComparingTo("2000000");}
