 @Test void tc19_refundReplayHasOneActualPayout(){var a=active("3000000",false);long co=request(a);inspect(a,co);approve(a,co,true);apply(a,co);long refund=refund(co);f.run(()->f.ledger.approveRefund(f.owner,a.deposit,refund));String key=f.key();Cash cash=f.cash("3000000");f.run(()->f.ledger.payRefund(f.accountant,a.deposit,refund,key,cash));f.run(()->f.ledger.payRefund(f.accountant,a.deposit,refund,key,cash));assertThat(count("deposit_transactions","deposit_id="+a.deposit+" AND transaction_type='REFUND'")).isOne();}
