 @Test void tc21_failedRefundRollsBackCash(){var a=active("1000000",false);long co=request(a);inspect(a,co);approve(a,co,true);apply(a,co);long refund=refund(co);f.run(()->f.ledger.approveRefund(f.owner,a.deposit,refund));assertThatThrownBy(()->f.run(()->{f.ledger.payRefund(f.accountant,a.deposit,refund,f.key(),f.cash("1000000"));throw new IllegalStateException("Failed downstream bank posting");})).isInstanceOf(IllegalStateException.class);assertThat(f.balance(a.deposit)).isEqualByComparingTo("1000000");assertThat(count("deposit_refund_requests","id="+refund+" AND paid_amount=0")).isOne();}
 @Test void tc22_offsetReducesDebtWithoutNewCashReceipt(){var a=active("1000000",false);oldDebt(a,"500000");long co=request(a);inspect(a,co);approve(a,co,true);apply(a,co);assertThat(f.accounting.outstandingDebt(3,a.property)).isZero();assertThat(count("payments","property_id="+a.property)).isZero();assertThat(f.db.sql("SELECT SUM(x.amount) FROM deposit_invoice_allocations x JOIN invoices i ON i.id=x.invoice_id WHERE i.contract_id=:id").param("id",a.contract).query(BigDecimal.class).single()).isEqualByComparingTo("500000");}
 @Test void tc23_tenantCanStillSeeUnpaidInvoiceAfterHandover(){var a=active("0",false);long old=oldDebt(a,"1000000");long co=request(a);inspect(a,co);approve(a,co,true);apply(a,co);var service=new com.thangit.boardinghouse.service.impl.TenantInvoiceServiceImpl(new TenantInvoiceRepository(f.db));assertThat(service.detail(f.tenant,old).remainingAmount()).isEqualByComparingTo("1000000");error("CHECKOUT_FINANCE_PENDING",()->f.run(()->f.ledger.closeCheckout(f.owner,a.deposit)));}
 @Test void tc24_parallelCheckoutHasOneSettlement() throws Exception {var a=active("1000000",false);long co=request(a);inspect(a,co);charge(co,"200000",true);approve(a,co,true);var r=completion(a,co);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{Callable<Boolean> task=()->{start.await();try{f.run(()->f.lifecycle.completeCheckout(f.owner,co,r));return true;}catch(com.thangit.boardinghouse.common.exception.AuthException e){return false;}};var x=pool.submit(task);var y=pool.submit(task);start.countDown();assertThat(List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS))).containsExactlyInAnyOrder(true,false);assertThat(count("invoices","code='QT-"+co+"'")).isOne();assertThat(count("deposit_transactions","checkout_id="+co+" AND transaction_type='DEDUCT'")).isOne();}finally{pool.shutdownNow();}}
