 @Test void tc28_roomNeedsExplicitAcceptanceBeforeReady(){var a=active("0",false);long co=request(a);inspect(a,co,null,null,false,true,null,assets(a));approve(a,co,true);apply(a,co);var properties=new AdminPropertyServiceImpl(new AdminPropertyRepository(f.db),new RoomLifecycleGuard(f.db));long v=f.db.sql("SELECT version FROM rooms WHERE id=:id").param("id",a.room).query(Long.class).single();error("ROOM_MAINTENANCE_PENDING",()->f.run(()->properties.changeStatus(f.owner,a.room,new ChangeStatus("READY","Not inspected yet",v,true))));}
 @Test void tc29_otherTenantCannotReadOrChangeCheckout(){var a=active("0",false);long co=request(a);var other=new AuthenticatedUser(6L,"other@test.invalid",RoleCode.TENANT);error("CHECKOUT_ACCESS_DENIED",()->workflow.detail(other,a.contract));error("CHECKOUT_ACCESS_DENIED",()->f.run(()->workflow.cancel(other,co,new VersionedReason(0L,"Tamper"))));}
 @Test void tc30_accountantCannotRefundOutsideScope(){var a=active("1000000",false);long co=request(a);inspect(a,co);approve(a,co,true);apply(a,co);long refund=refund(co);f.run(()->f.ledger.approveRefund(f.owner,a.deposit,refund));f.db.sql("DELETE FROM accountant_property_assignments WHERE accountant_id=4 AND property_id=:id").param("id",a.property).update();error("DEPOSIT_ACCESS_DENIED",()->f.run(()->f.ledger.payRefund(f.accountant2,a.deposit,refund,f.key(),f.cash("1000000"))));}
 @Test void tc31_technicianCannotApproveOrTerminate(){var a=active("0",false);long co=request(a);var tech=new AuthenticatedUser(6L,"tech@test.invalid",RoleCode.TECHNICIAN);error("CHECKOUT_ACCESS_DENIED",()->f.run(()->workflow.approveSchedule(tech,co,new Schedule(LocalDate.now(),0L,"Tamper","REF"))));}
 @Test void tc32_settlementInvoiceHasSourceAndAudit(){var a=active("0",false);long co=request(a);inspect(a,co);charge(co,"200000",true);approve(a,co,true);apply(a,co);long invoice=f.db.sql("SELECT id FROM invoices WHERE code=:code").param("code","QT-"+co).query(Long.class).single();assertThat(invoices.items(invoice).getFirst().sourceType()).isEqualTo("CHECKOUT_FINAL");assertThat(count("invoice_history","invoice_id="+invoice+" AND action='CHECKOUT_SETTLEMENT'")).isOne();}
 @Test void tc33_offsetDoesNotDuplicateCashbook(){var a=active("1000000",false);long co=request(a);inspect(a,co);charge(co,"200000",true);approve(a,co,true);apply(a,co);var book=f.accounting.books(3L,a.property,period.toString().substring(0,7),"CASH",0,100);assertThat(((Number)book.get("totalElements")).longValue()).isOne();assertThat(count("payments","property_id="+a.property)).isZero();}
 @Test void tc34_reportsUseNetRemainingAfterDeposit(){var a=active("1000000",false);oldDebt(a,"500000");long co=request(a);inspect(a,co);charge(co,"200000",true);approve(a,co,true);apply(a,co);var s=invoices.summary(1,RoleCode.OWNER,a.property,null);assertThat(s.totalInvoiceAmount()).isEqualByComparingTo("700000");assertThat(s.totalPaidAmount()).isEqualByComparingTo("700000");assertThat(s.totalOutstandingAmount()).isZero();assertThat(f.accounting.outstandingDebt(3,a.property)).isZero();}
 @Test void cancelledRequestCanBeReplacedWithoutDeletingHistory(){var a=active("0",false);long first=request(a);f.run(()->workflow.cancel(f.tenant,first,new VersionedReason(0L,"Staying longer")));long second=request(a);assertThat(second).isNotEqualTo(first);assertThat(count("rental_checkouts","contract_id="+a.contract)).isEqualTo(2);assertThat(count("checkout_history","checkout_id="+first+" AND event_type='CANCELLED'")).isOne();}
