 @Test void originalContractEndIsPreservedAfterClosure(){var a=active("0",false);LocalDate original=LocalDate.now().plusYears(1);long co=request(a);inspect(a,co);approve(a,co,true);apply(a,co);f.run(()->f.ledger.closeCheckout(f.owner,a.deposit));assertThat(f.db.sql("SELECT end_date FROM contracts WHERE id=:id").param("id",a.contract).query(LocalDate.class).single()).isEqualTo(original);assertThat(count("contracts","id="+a.contract+" AND status='TERMINATED' AND operational_ended_at IS NOT NULL AND financially_closed_at IS NOT NULL")).isOne();assertThat(workflow.document(f.tenant,a.contract)).contains("COMPLETED");}
