 @Test void physicalHandoverDoesNotPretendFinancialCompletion(){var a=active("1000000",false);oldDebt(a,"500000");long co=request(a);inspect(a,co);confirmInspection(a,co);f.run(()->workflow.handover(f.owner,co,new VersionedReason(version(co),"Keys and possession actually returned")));assertThat(count("rooms","id="+a.room+" AND status='CLEANING'")).isOne();assertThat(count("contracts","id="+a.contract+" AND status='SETTLING'")).isOne();assertThat(f.balance(a.deposit)).isEqualByComparingTo("1000000");assertThat(count("deposit_transactions","deposit_id="+a.deposit+" AND transaction_type='DEDUCT'")).isZero();error("CHECKOUT_RECONCILIATION_REQUIRED",()->f.run(()->f.ledger.closeCheckout(f.owner,a.deposit)));}
 @Test void lateFinancialSettlementCannotChangeNewBookingRoomState(){var a=active("1000000",false);oldDebt(a,"500000");long co=request(a);inspect(a,co);confirmInspection(a,co);f.run(()->workflow.handover(f.owner,co,new VersionedReason(version(co),"Physical handover before review finished")));var properties=new AdminPropertyServiceImpl(new AdminPropertyRepository(f.db),new RoomLifecycleGuard(f.db));long roomVersion=f.db.sql("SELECT version FROM rooms WHERE id=:id").param("id",a.room).query(Long.class).single();f.run(()->properties.changeStatus(f.owner,a.room,new ChangeStatus("READY","Turnover inspected and complete",roomVersion,true)));long profile=f.insert("INSERT INTO tenant_profiles(tenant_code,user_id,full_name,phone) VALUES('"+f.key().substring(0,20)+"',6,'Next resident','"+f.key().substring(0,18)+"')");f.db.sql("INSERT INTO tenant_residences(tenant_profile_id,property_id,move_in_date) VALUES(:profile,:property,CURRENT_DATE)").param("profile",profile).param("property",a.property).update();f.run(()->f.lifecycle.createBooking(f.owner,new CreateBooking(profile,a.room,LocalDate.now(),LocalDate.now().plusDays(7),BigDecimal.ZERO,null,null)));approve(a,co,true);apply(a,co);assertThat(count("rooms","id="+a.room+" AND status='RESERVED'")).isOne();assertThat(f.balance(a.deposit)).isEqualByComparingTo("500000");}
 @Test void physicalHandoverCanProceedWhileMoneyDisputeRemainsOpen(){var a=active("0",false);long co=request(a);inspect(a,co);confirmInspection(a,co);f.run(()->workflow.dispute(f.tenant,co,new Dispute("I return the room but dispute a proposed fee")));f.run(()->workflow.handover(f.owner,co,new VersionedReason(version(co),"Confirmed inspection, money dispute retained")));assertThat(count("rooms","id="+a.room+" AND status='CLEANING'")).isOne();assertThat(count("checkout_disputes","checkout_id="+co+" AND status='OPEN'")).isOne();assertThat(count("rental_checkouts","id="+co+" AND settlement_applied_at IS NULL")).isOne();}
